// ─── Player types ───

import type { AvatarId, MediaId } from './account';
import type { AvatarBorderId } from '../constants/shop';

/** Unique player id (generated by the server) */
export type PlayerId = string;

/** Seat position */
export type Seat = 'N' | 'E' | 'S' | 'W';
export type AdditionalSeat = 'P5' | 'P6' | 'P7' | 'P8';
export type GameSeat = Seat | AdditionalSeat;

/** Player color (hex code) */
export type PlayerColor = string;

/** Player info */
export interface PlayerInfo {
  readonly id: PlayerId;
  readonly username: string;
  readonly nickname: string;
  readonly color: PlayerColor;
  readonly avatar: AvatarId;
  readonly avatarImage: MediaId | null;
  readonly avatarBorder?: AvatarBorderId | null;
  /** Public waiting-room seat artwork; omitted/null keeps the theme background. */
  readonly seatBackground?: MediaId | null;
  readonly isBot?: boolean;
}

/** Player connection status */
export type ConnectionStatus = 'connected' | 'disconnected';
